/* @autogenerated */
package net.civeira.phylax.features.oauth.magiclink.domain;

import java.time.OffsetDateTime;
import java.time.ZoneOffset;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

class MagicLinkUnitTest {

  private MagicLink.MagicLinkBuilder baseBuilder() {
    return MagicLink.builder().uid("uid-1").tenantId("tenant").userUid("user-1")
        .clientId("client-1").tokenHash("hash123").redirectUri("https://app.example.com/callback")
        .scope("openid profile").createdAt(OffsetDateTime.now(ZoneOffset.UTC));
  }

  @Test
  @DisplayName("not expired when expiresAt is in the future")
  void test_not_expired() {
    MagicLink link =
        baseBuilder().expiresAt(OffsetDateTime.now(ZoneOffset.UTC).plusHours(1)).build();
    Assertions.assertFalse(link.isExpired());
  }

  @Test
  @DisplayName("expired when expiresAt is in the past")
  void test_expired() {
    MagicLink link =
        baseBuilder().expiresAt(OffsetDateTime.now(ZoneOffset.UTC).minusSeconds(1)).build();
    Assertions.assertTrue(link.isExpired());
  }

  @Test
  @DisplayName("not used when usedAt is null")
  void test_not_used() {
    MagicLink link =
        baseBuilder().expiresAt(OffsetDateTime.now(ZoneOffset.UTC).plusHours(1)).build();
    Assertions.assertFalse(link.isUsed());
    Assertions.assertFalse(link.getUsedAt().isPresent());
  }

  @Test
  @DisplayName("used when usedAt is set")
  void test_used() {
    MagicLink link = baseBuilder().expiresAt(OffsetDateTime.now(ZoneOffset.UTC).plusHours(1))
        .usedAt(OffsetDateTime.now(ZoneOffset.UTC)).build();
    Assertions.assertTrue(link.isUsed());
    Assertions.assertTrue(link.getUsedAt().isPresent());
  }

  @Test
  @DisplayName("valid when not expired and not used")
  void test_valid() {
    MagicLink link =
        baseBuilder().expiresAt(OffsetDateTime.now(ZoneOffset.UTC).plusHours(1)).build();
    Assertions.assertTrue(link.isValid());
  }

  @Test
  @DisplayName("invalid when expired")
  void test_invalid_when_expired() {
    MagicLink link =
        baseBuilder().expiresAt(OffsetDateTime.now(ZoneOffset.UTC).minusSeconds(1)).build();
    Assertions.assertFalse(link.isValid());
  }

  @Test
  @DisplayName("invalid when used")
  void test_invalid_when_used() {
    MagicLink link = baseBuilder().expiresAt(OffsetDateTime.now(ZoneOffset.UTC).plusHours(1))
        .usedAt(OffsetDateTime.now(ZoneOffset.UTC)).build();
    Assertions.assertFalse(link.isValid());
  }

  @Test
  @DisplayName("getState returns empty when null and present when set")
  void test_state_optional() {
    MagicLink withoutState =
        baseBuilder().expiresAt(OffsetDateTime.now(ZoneOffset.UTC).plusHours(1)).build();
    Assertions.assertFalse(withoutState.getState().isPresent());

    MagicLink withState = baseBuilder().expiresAt(OffsetDateTime.now(ZoneOffset.UTC).plusHours(1))
        .state("state-xyz").build();
    Assertions.assertTrue(withState.getState().isPresent());
    Assertions.assertEquals("state-xyz", withState.getState().get());
  }
}
